#!/usr/bin/env bash
# Create the API environment file with a fresh analytics HMAC key.
# Writes ./.secrets/api.env (mode 0600, gitignored). Never print the key.
set -euo pipefail

REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
OUT_DIR="$REPO_DIR/.secrets"
OUT="$OUT_DIR/api.env"

umask 077
mkdir -p "$OUT_DIR"
chmod 700 "$OUT_DIR"

if [ -f "$OUT" ] && [ "${SHARAPA_FORCE_NEW_KEY:-0}" != "1" ]; then
  echo "keeping existing $OUT (set SHARAPA_FORCE_NEW_KEY=1 to rotate)"
  exit 0
fi

KEY="$(python3 -c 'import secrets; print(secrets.token_hex(32))')"

cat > "$OUT" <<EOF
# Generated by deploy/generate-secrets.sh. Mode 0600. Do not commit.
SHARAPA_API_DATABASE=/var/lib/sharapa-api/site.sqlite3
SHARAPA_GEOIP_DATABASE=/var/lib/sharapa-api/ip-to-country.mmdb
SHARAPA_ALLOWED_ORIGINS=https://www.sharapa.io,https://sharapa.io
SHARAPA_ANALYTICS_HMAC_KEY=$KEY
EOF
chmod 600 "$OUT"
unset KEY

echo "wrote $OUT (mode $(stat -c '%a' "$OUT"))"
echo "key length: $(awk -F= '/^SHARAPA_ANALYTICS_HMAC_KEY=/{print length($2)}' "$OUT")"
